    "subtopic": "Transitions",
    "difficulty": "easy",
    "passage": "Practical movie effects, such as the use of actual locations in a film, provide a more realistic visual experience than computer-generated imagery (CGI) does, but giving audiences the “real thing” can be prohibitively expensive. ______ many filmmakers use a blended approach, employing practical effects whenever possible and CGI elements as necessary to control costs.",
