    "passage": "For years, biologists have experimented with using grime-eating bacteria rather than harsh chemicals to clean ar tworks, and results have been impressive overall. ______ these bacterial strains—which can metabolize centuries’ wor th of oil, glue, dir t, and other surface impurities without creating harmful byproducts—have proven more effective than traditional chemical cleaning methods.",
