    "passage": "Karel Čapek’s 1920 play R.U.R. (Rossum’s Universal Robots), in which ar tificial workers over throw their masters, left an indelible mark on the science fiction genre, and the English language, by introducing the term “robot” (derived from the Czech word robota, meaning “indentured labor” or “drudgery”). ______ Čapek’s play also contributed to a venerable literary and mythological tradition: using ar tificial beings as mirrors and foils for humanity.",
