    "subtopic": "Transitions",
    "difficulty": "hard",
    "passage": "In a heated debate in biogeography, the field is divided between dispersalists and vicariancists. ______ there are those who argue that dispersal is the most crucial determining factor in a species’ distribution, and those who insist that vicariance (separation due to geographic barriers) is. Biogeographer Isabel Sanmar tín counts herself among neither.",
