    "subtopic": "Transitions",
    "difficulty": "hard",
    "passage": "Because an achiral molecule is symmetrical, flipping it yields a structurally identical molecule. A flipped chiral molecule, ______ can be compared to a glove that has been turned inside out: it produces a structurally inver ted molecule rather than an identical one.",
