    "passage": "In Asiya Wadud’s 2022 poem “Shorn, Treaded Red, ” the poet contemplates a painting that has inspired her: Etel Adnan’s 2020 work Satellites 27. The painting, which features overlapping geometric shapes, fuels the poem’s exploration of temporality and identity. ______ in responding to Adnan’s ar twork, Wadud’s poem reflects on the relationship between poetry and other art forms.",
