    "subtopicId": "transitions",
    "subtopic": "Transitions",
    "difficulty": "hard",
    "passage": "A staunch suppor ter of women’s voting rights, Wilhelmina Kekelaokalaninui Widemann Dowsett sought to coordinate the effor ts of suffragists in her native Hawai‘i. ______ in 1912, she founded the National Women’s Equal Suffrage Association of Hawai‘i, an organization that lobbied for women’s voting rights in the US territory.",
