    "difficulty": "hard",
    "passage": "In his 2023 collection The Diaspora Sonnets, Filipino American poet Oliver de la Paz leverages the sonnet form’s “diamond-like quality of precision, ” as he describes it. The poems often adhere scrupulously to the form’s centuries-old conventions, such as its characteristic four teen- line length. In the twelve-line poem “Diaspora Sonnet at the Feeders Before the Freeze, ” ______ de la Paz playfully subver ts sonnet conventions, the poem’s truncated length conveying a sense of abruptness.",
